import React from 'react';
import { Link, useHistory } from 'react-router-dom';
import { useState } from 'react';
import axios from 'axios';

function Navbar({ userId }) {
  const [searchQuery, setSearchQuery] = useState('');
  const history = useHistory();

  const handleSearch = async (e) => {
    if (e.key === 'Enter' && searchQuery.trim()) {
      try {
        const res = await axios.get(`http://localhost:5000/search/recipes?q=${searchQuery}`);
        history.push('/recipes', { recipes: res.data });
      } catch (error) {
        alert('Search failed');
      }
    }
  };

  return (
    <nav style={{ padding: '10px', background: '#333', color: 'white', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
      <div>
        <Link to="/" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Home</Link>
        {!userId ? (
          <Link to="/signin" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Sign In</Link>
        ) : (
          <>
            <Link to="/dashboard" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Dashboard</Link>
            <Link to="/recipes" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Recipes</Link>
            <Link to="/ask" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Ask AI</Link>
            <Link to="/payment" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Upgrade</Link>
            <Link to="/profile" style={{ color: 'white', margin: '0 10px', textDecoration: 'none' }}>Profile</Link>
          </>
        )}
      </div>
      <input
        type="text"
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
        onKeyPress={handleSearch}
        placeholder="Search recipes..."
        style={{ padding: '5px', margin: '0 10px', borderRadius: '4px', border: 'none' }}
      />
    </nav>
  );
}

export default Navbar;
